namespace {
void Require(bool okay,const char *why){if(!okay)throw std::runtime_error(why);}
QString Hash(const QByteArray &bytes){return QString::fromLatin1(QCryptographicHash::hash(bytes,QCryptographicHash::Sha256).toHex());}
QString Marker(const QString &path){return QFileInfo(path).absolutePath()+"/.getdaq-workspace-save-"+Hash(path.toUtf8())+".json";}
void SyncDirectory(const QString &path){
#ifdef Q_OS_UNIX
    const int fd=::open(path.toUtf8().constData(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);Require(fd>=0,"Cannot open configuration directory for sync");const int result=::fsync(fd);::close(fd);Require(result==0,"Cannot sync configuration directory");
#else
    Q_UNUSED(path); // Windows file _commit is verified; directory power-loss persistence is not claimed.
#endif
}
void SyncFile(QFile &file){Require(file.flush(),"Cannot flush configuration recovery file");
#ifdef Q_OS_UNIX
    Require(::fsync(file.handle())==0,"Cannot sync configuration recovery file");
#elif defined(Q_OS_WIN)
    Require(::_commit(file.handle())==0,"Cannot sync configuration recovery file");
#endif
}
QByteArray Read(const QString &path,qint64 maximum){const QFileInfo info(path);Require(info.isFile() && !info.isSymLink() && info.size()>=0 && info.size()<=maximum,"Invalid/bounded configuration recovery file");QFile file(path);Require(file.open(QIODevice::ReadOnly),"Cannot read configuration recovery file");const auto bytes=file.read(maximum+1);Require(bytes.size()<=maximum && file.error()==QFile::NoError,"Configuration recovery file read failed");return bytes;}
QJsonObject Json(const QByteArray &bytes){GetDAQ::ParseStrictJson(bytes.toStdString());QJsonParseError error;const auto doc=QJsonDocument::fromJson(bytes,&error);Require(error.error==QJsonParseError::NoError && doc.isObject(),"Invalid recovery metadata JSON");return doc.object();}
void Fields(const QJsonObject &o,const QStringList &keys){Require(o.keys().size()==keys.size(),"Unknown recovery metadata fields");for(const auto &key:keys)Require(o.contains(key),"Missing recovery metadata field");}
QString String(const QJsonObject &o,const QString &name){Require(o[name].isString(),"Recovery field must be a string");return o[name].toString();}
void GuardDirectory(const QString &path,bool create){if(create)Require(QDir().mkdir(path),"Cannot exclusively create recovery directory");const QFileInfo info(path);Require(info.isDir() && !info.isSymLink() && info.canonicalFilePath()==info.absoluteFilePath(),"Recovery directory identity/path invalid");if(create)Require(QFile::setPermissions(path,QFile::ReadOwner|QFile::WriteOwner|QFile::ExeOwner),"Cannot protect recovery directory");
#ifdef Q_OS_UNIX
    struct stat value;Require(::lstat(path.toUtf8().constData(),&value)==0 && value.st_uid==::geteuid() && (value.st_mode&0777)==0700,"Recovery directory owner/permissions invalid");
#endif
    if(create)SyncDirectory(QFileInfo(path).absolutePath());
}
void Write(const QString &path,const QByteArray &bytes){QFile file(path);Require(file.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Recovery file exists or cannot be created");Require(file.setPermissions(QFile::ReadOwner|QFile::WriteOwner),"Cannot protect recovery file");Require(file.write(bytes)==bytes.size(),"Recovery file write incomplete");SyncFile(file);file.close();SyncDirectory(QFileInfo(path).absolutePath());}
QByteArray MarkerBytes(const QString &source,const QString &directory,const QString &key){QJsonObject o;o["schema"]=1;o["kind"]="getdaq.workspace-save-marker";o["source"]=source;o["directory"]=directory;o["manifest_sha256"]=key;return QJsonDocument(o).toJson(QJsonDocument::Compact);}
struct Snapshot {QStringList roots;QMap<QString,QByteArray> before,after;QByteArray manifest;QString key;};
Snapshot Load(const QString &directory){GuardDirectory(directory,false);GuardDirectory(directory+"/original",false);GuardDirectory(directory+"/candidate",false);Snapshot s;s.manifest=Read(directory+"/manifest.json",2*1024*1024);s.key=Hash(s.manifest);const auto m=Json(s.manifest);Fields(m,{"schema","kind","roots","files"});Require(m["schema"].toInt()==1 && String(m,"kind")=="getdaq.workspace-save-intent","Unsupported recovery manifest");Require(m["roots"].isArray() && m["files"].isArray(),"Recovery roots/files must be arrays");const auto rows=m["files"].toArray();Require(!rows.isEmpty() && rows.size()<=256 && !m["roots"].toArray().isEmpty() && m["roots"].toArray().size()<=16,"Recovery source/root budget");qint64 total=0;
    for(const auto &root:m["roots"].toArray()){Require(root.isString(),"Recovery root type");Require(!s.roots.contains(root.toString()),"Duplicate recovery root");s.roots.append(root.toString());}
    for(int i=0;i<rows.size();++i){Require(rows[i].isObject(),"Recovery file record type");const auto row=rows[i].toObject();Fields(row,{"path","before_sha256","after_sha256","changed"});const auto path=String(row,"path");Require(QFileInfo(path).isAbsolute() && QFileInfo(path).canonicalFilePath()==path && !s.before.contains(path) && row["changed"].isBool(),"Recovery source path/type invalid");const auto before=Read(directory+"/original/"+QString::number(i)+".xcfg",8*1024*1024);const auto after=row["changed"].toBool() ? Read(directory+"/candidate/"+QString::number(i)+".xcfg",8*1024*1024) : before;Require(Hash(before)==String(row,"before_sha256") && Hash(after)==String(row,"after_sha256"),"Recovery payload hash differs");total+=before.size()+after.size();Require(total<=128LL*1024*1024,"Recovery byte budget");s.before[path]=before;s.after[path]=after;}
    for(const auto &root:s.roots)
        Require(s.before.contains(root),"Recovery root not in original source set");
    return s;
}
bool Completed(const QString &directory,const QString &key){const auto path=directory+"/complete.json";if(!QFileInfo::exists(path))return false;const auto o=Json(Read(path,4096));Fields(o,{"schema","kind","manifest_sha256","outcome"});Require(o["schema"].toInt()==1 && String(o,"kind")=="getdaq.workspace-save-complete" && String(o,"manifest_sha256")==key,"Recovery completion binding differs");const auto outcome=String(o,"outcome");Require(outcome=="candidate" || outcome=="original","Recovery completion outcome invalid");return true;}
void Cleanup(const QString &directory,const QString &key,const QMap<QString,QByteArray> &sources){for(auto it=sources.constBegin();it!=sources.constEnd();++it){const auto path=Marker(it.key());if(!QFileInfo::exists(path))continue;Require(Read(path,8192)==MarkerBytes(it.key(),directory,key),"Recovery marker differs during completion");Require(QFile::remove(path),"Cannot remove completed configuration marker");SyncDirectory(QFileInfo(path).absolutePath());}}
QString Failure(const std::exception &e){return QString::fromUtf8(e.what());}
}
XcfgSaveJournal::XcfgSaveJournal(){}
XcfgSaveJournal::~XcfgSaveJournal(){}
bool XcfgSaveJournal::Pending(const QString &source,QString *directory,QString *error){try{directory->clear();const auto path=Marker(source);if(!QFileInfo::exists(path)){error->clear();return true;}const auto bytes=Read(path,8192);const auto o=Json(bytes);Fields(o,{"schema","kind","source","directory","manifest_sha256"});Require(o["schema"].toInt()==1 && String(o,"kind")=="getdaq.workspace-save-marker" && String(o,"source")==source,"Pending save source binding differs");const auto folder=String(o,"directory"),key=String(o,"manifest_sha256");GuardDirectory(folder,false);Require(Hash(Read(folder+"/manifest.json",2*1024*1024))==key,"Pending save manifest hash differs");if(!Completed(folder,key))*directory=folder;error->clear();return true;}catch(const std::exception &e){*error=Failure(e);return false;}}
bool XcfgSaveJournal::Begin(const QStringList &roots,const QMap<QString,QByteArray> &original,const QMap<QString,QByteArray> &writes,QString *error){
    XcfgIoTransaction ioTransaction(error,XcfgIoTransaction::Write);if(!ioTransaction.IsLocked())return false;
try{Require(fDirectory.isEmpty() && !roots.isEmpty() && !writes.isEmpty() && original.size()<=256,"Invalid configuration save journal begin");for(auto it=original.constBegin();it!=original.constEnd();++it){QString pending;Require(Pending(it.key(),&pending,error) && pending.isEmpty(),"Source has a pending save; inspect recovery first");}
    const auto parent=QFileInfo(roots.first()).absolutePath(),base=parent+"/.getdaq-workspace-recovery";if(!QFileInfo::exists(base))GuardDirectory(base,true);else GuardDirectory(base,false);const auto records=QDir(base).entryInfoList(QDir::Dirs|QDir::NoDotAndDotDot);Require(records.size()<256,"Recovery record limit reached; archive completed records first");qint64 retained=0;for(const auto &record:records){Require(!record.isSymLink(),"Unexpected recovery directory symlink");for(const auto &part:{QString("original"),QString("candidate")})for(const auto &file:QDir(record.filePath()+'/'+part).entryInfoList(QDir::Files)){Require(!file.isSymLink(),"Unexpected recovery payload symlink");retained+=file.size();Require(retained<=2LL*1024*1024*1024,"Recovery storage limit reached; archive completed records first");}}qint64 additional=0;for(auto it=original.constBegin();it!=original.constEnd();++it)additional+=it->size();for(auto it=writes.constBegin();it!=writes.constEnd();++it)if(it.value()!=original.value(it.key()))additional+=it->size();Require(retained+additional<=2LL*1024*1024*1024,"Recovery storage limit would be exceeded; no source replaced");fDirectory=base+"/save-"+QUuid::createUuid().toString(QUuid::WithoutBraces);GuardDirectory(fDirectory,true);GuardDirectory(fDirectory+"/original",true);GuardDirectory(fDirectory+"/candidate",true);fLock.reset(new QLockFile(fDirectory+"/writer.lock"));fLock->setStaleLockTime(0);Require(fLock->tryLock(0),"Cannot own recovery writer lock");QJsonObject manifest;manifest["schema"]=1;manifest["kind"]="getdaq.workspace-save-intent";QJsonArray rootRows,fileRows;for(const auto &root:roots)rootRows.append(root);manifest["roots"]=rootRows;int index=0;qint64 total=0;
    for(auto it=original.constBegin();it!=original.constEnd();++it,++index){const auto after=writes.value(it.key(),it.value());Require(it->size()<=8*1024*1024 && after.size()<=8*1024*1024,"Save recovery file exceeds 8 MiB");total+=it->size()+after.size();Require(total<=128LL*1024*1024,"Save recovery sources exceed 128 MiB");Write(fDirectory+"/original/"+QString::number(index)+".xcfg",it.value());if(after!=it.value())Write(fDirectory+"/candidate/"+QString::number(index)+".xcfg",after);QJsonObject row;row["path"]=it.key();row["before_sha256"]=Hash(it.value());row["after_sha256"]=Hash(after);row["changed"]=after!=it.value();fileRows.append(row);}
    manifest["files"]=fileRows;fManifest=QJsonDocument(manifest).toJson(QJsonDocument::Compact);Require(fManifest.size()<=2*1024*1024,"Save recovery manifest exceeds 2 MiB");Write(fDirectory+"/manifest.json",fManifest);fKey=Hash(fManifest);
    for(auto it=original.constBegin();it!=original.constEnd();++it){const auto path=Marker(it.key());if(QFileInfo::exists(path)){const auto old=Json(Read(path,8192));Require(Completed(String(old,"directory"),String(old,"manifest_sha256")),"Existing source marker is unfinished");Require(QFile::remove(path),"Cannot retire completed source marker");SyncDirectory(QFileInfo(path).absolutePath());}const auto bytes=MarkerBytes(it.key(),fDirectory,fKey);Write(path,bytes);fMarkers[path]=bytes;}
    return Check(error);
}catch(const std::exception &e){*error=Failure(e);return false;}}
bool XcfgSaveJournal::Check(QString *error) const {try{GuardDirectory(fDirectory,false);Require(fLock && fLock->isLocked() && Read(fDirectory+"/manifest.json",2*1024*1024)==fManifest,"Save journal binding changed");for(auto it=fMarkers.constBegin();it!=fMarkers.constEnd();++it)Require(Read(it.key(),8192)==it.value(),"Save journal source marker changed");error->clear();return true;}catch(const std::exception &e){*error=Failure(e);return false;}}
bool XcfgSaveJournal::Complete(const QString &outcome,QString *error){
    XcfgIoTransaction ioTransaction(error,XcfgIoTransaction::Write);if(!ioTransaction.IsLocked())return false;
try{Require(Check(error),"Save journal changed before completion");Require(outcome=="candidate" || outcome=="original","Invalid recovery outcome");const auto s=Load(fDirectory);const auto &expected=outcome=="candidate" ? s.after : s.before;for(auto it=expected.constBegin();it!=expected.constEnd();++it)Require(Read(it.key(),8*1024*1024)==it.value(),"Saved source differs before journal completion");QJsonObject o;o["schema"]=1;o["kind"]="getdaq.workspace-save-complete";o["manifest_sha256"]=fKey;o["outcome"]=outcome;Write(fDirectory+"/complete.json",QJsonDocument(o).toJson(QJsonDocument::Compact));Cleanup(fDirectory,fKey,expected);error->clear();return true;}catch(const std::exception &e){*error=Failure(e);return false;}}
bool XcfgSaveJournal::SyncSource(const QString &path,QString *error){try{QFile file(path);Require(file.open(QIODevice::ReadWrite),"Cannot open saved source for sync");SyncFile(file);file.close();SyncDirectory(QFileInfo(path).absolutePath());error->clear();return true;}catch(const std::exception &e){*error=Failure(e);return false;}}
bool XcfgSaveJournal::PreviewRecovery(const QString &directory,bool candidate,Recovery *preview,QString *error){
    XcfgIoTransaction ioTransaction(error);if(!ioTransaction.IsLocked())return false;
try{Require(preview,"No recovery preview destination");const auto s=Load(directory);Require(!Completed(directory,s.key),"Save record already completed; recovery is not replayed");QLockFile lock(directory+"/writer.lock");lock.setStaleLockTime(0);Require(lock.tryLock(0),"Original save/recovery writer is still active");Recovery result;result.directory=directory;result.manifestSha256=s.key;result.roots=s.roots;result.target=candidate ? s.after : s.before;result.candidate=candidate;QJsonArray files;
    for(auto it=s.before.constBegin();it!=s.before.constEnd();++it){const auto current=Read(it.key(),8*1024*1024);Require(current==it.value() || current==s.after.value(it.key()),"Current source is neither original nor candidate; refuse recovery overwrite");QString pending;Require(Pending(it.key(),&pending,error) && (pending.isEmpty() || pending==directory),"Source belongs to another pending save");result.observed[it.key()]=current;QJsonObject row;row["path"]=it.key();row["current"]=current==it.value() ? "original" : "candidate";row["will_replace"]=current!=result.target.value(it.key());row["current_sha256"]=Hash(current);row["target_sha256"]=Hash(result.target.value(it.key()));files.append(row);}
    QMap<QString,XcfgDocument> docs;QMap<QString,QByteArray> sources;Require(XcfgWorkspace::Build(s.roots,result.target,&docs,&sources,error),"Recovery target configuration is invalid");for(auto it=result.target.constBegin();it!=result.target.constEnd();++it)if(!sources.contains(it.key())){QMap<QString,XcfgDocument> detached;QMap<QString,QByteArray> dependencies;Require(XcfgWorkspace::Build(QStringList{it.key()},result.target,&detached,&dependencies,error),"Detached recovery source is invalid");for(auto d=dependencies.constBegin();d!=dependencies.constEnd();++d)sources[d.key()]=d.value();}Require(sources.size()==s.before.size(),"Recovery target dependency set differs");for(auto it=sources.constBegin();it!=sources.constEnd();++it)Require(result.target.value(it.key())==it.value(),"Recovery dependency differs");result.report["kind"]="getdaq.workspace-save-recovery";result.report["direction"]=candidate ? "candidate" : "original";result.report["files"]=files;result.report["disk_written"]=false;result.report["hardware_loaded_verified"]=false;*preview=result;error->clear();return true;
}catch(const std::exception &e){*error=Failure(e);return false;}}
bool XcfgSaveJournal::ApplyRecovery(const Recovery &preview,QString *error){
    XcfgIoTransaction ioTransaction(error,XcfgIoTransaction::Write);if(!ioTransaction.IsLocked())return false;
try{Recovery current;if(!PreviewRecovery(preview.directory,preview.candidate,&current,error))return false;Require(current.manifestSha256==preview.manifestSha256 && current.roots==preview.roots && current.observed==preview.observed && current.target==preview.target && current.report==preview.report,"Recovery review changed; inspect a new review");QLockFile lock(preview.directory+"/writer.lock");lock.setStaleLockTime(0);Require(lock.tryLock(0),"Recovery writer busy");Require(!Completed(preview.directory,current.manifestSha256),"Recovery record completed after review; no replay");for(auto it=current.observed.constBegin();it!=current.observed.constEnd();++it){QString pending;if(!Pending(it.key(),&pending,error))return false;Require(pending.isEmpty() || pending==preview.directory,"Recovery source belongs to another writer");const auto marker=Marker(it.key());if(!QFileInfo::exists(marker))Write(marker,MarkerBytes(it.key(),preview.directory,current.manifestSha256));else Require(Read(marker,8192)==MarkerBytes(it.key(),preview.directory,current.manifestSha256),"Recovery source marker differs");}std::vector<std::unique_ptr<QSaveFile>> files;QStringList paths;
    for(auto it=current.target.constBegin();it!=current.target.constEnd();++it)if(it.value()!=current.observed.value(it.key())){std::unique_ptr<QSaveFile> file(new QSaveFile(it.key()));file->setDirectWriteFallback(false);Require(file->open(QIODevice::WriteOnly) && file->write(it.value())==it->size(),"Cannot prepare recovery source replacement");paths.append(it.key());files.push_back(std::move(file));}
    const auto check=[&]{Require(!Completed(preview.directory,current.manifestSha256),"Recovery record completed; no replay");Require(Hash(Read(preview.directory+"/manifest.json",2*1024*1024))==current.manifestSha256,"Recovery manifest changed");for(auto it=current.observed.constBegin();it!=current.observed.constEnd();++it){Require(Read(Marker(it.key()),8192)==MarkerBytes(it.key(),preview.directory,current.manifestSha256),"Recovery source marker changed");Require(Read(it.key(),8*1024*1024)==it.value(),"Recovery source changed during replacement");}};check();
    for(std::size_t i=0;i<files.size();++i){check();Require(files[i]->commit(),"Recovery file commit failed; retained intent requires another review");Require(SyncSource(paths[int(i)],error),"Recovery source sync failed");current.observed[paths[int(i)]]=current.target.value(paths[int(i)]);}
    check();QJsonObject o;o["schema"]=1;o["kind"]="getdaq.workspace-save-complete";o["manifest_sha256"]=current.manifestSha256;o["outcome"]=preview.candidate ? "candidate" : "original";Write(preview.directory+"/complete.json",QJsonDocument(o).toJson(QJsonDocument::Compact));Cleanup(preview.directory,current.manifestSha256,current.target);error->clear();return true;
}catch(const std::exception &e){*error=Failure(e);return false;}}
